package com.enterpriseos;

import java.time.*;
import java.util.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class ReportService {
    private final AutomationSupport s;private final OperationsController workforce;private final CustomAccessPolicy custom;private final FeatureFlagService flags;
    public ReportService(AutomationSupport s,OperationsController workforce,CustomAccessPolicy custom,FeatureFlagService flags){this.s=s;this.workforce=workforce;this.custom=custom;this.flags=flags;}
    static final Set<String> KINDS=Set.of("employees","projects","audit","attendance","leaves","inventory","invoices","payroll");
    public void authorize(Principal p,String kind){s.org(p);if(!KINDS.contains(kind))throw new ApiException(400,"Choose a supported report kind.");flags.require(p.tenantId(),switch(kind){case "employees","attendance","leaves"->"HR";case "projects"->"PROJECTS";case "inventory"->"INVENTORY";case "invoices"->"FINANCE";case "payroll"->"PAYROLL";default->"REPORTS";});if(!custom.allowed(p,"GET",sourcePath(kind)))throw new ApiException(403,"Custom role cannot access the report source.");switch(kind){case "employees"->s.allow(p,"ADMIN","HR","AUDITOR");case "audit"->s.allow(p,"ADMIN","AUDITOR");case "inventory"->s.allow(p,"ADMIN","PROCUREMENT","AUDITOR");case "invoices"->s.allow(p,"ADMIN","FINANCE","AUDITOR");case "payroll"->s.allow(p,"ADMIN","FINANCE","PAYROLL","AUDITOR");case "attendance","leaves"->s.allow(p,"ADMIN","HR","MANAGER","MEMBER","AUDITOR");default->{}}}
    public List<Map<String,Object>> rows(Principal p,String kind,Map<String,Object> filters){authorize(p,kind);Set<String> allowed=Set.of("startDate","endDate","status");if(!allowed.containsAll(filters.keySet()))throw new ApiException(400,"Unsupported report filter.");LocalDate start=date(filters,"startDate"),end=date(filters,"endDate");if(start!=null&&end!=null&&end.isBefore(start))throw new ApiException(400,"Report end date must follow its start.");List<Map<String,Object>> result=switch(kind){case "employees","projects"->new ArrayList<>(workforce.list(p,kind));case "attendance"->new ArrayList<>(workforce.attendance(p));case "leaves"->new ArrayList<>(workforce.leaves(p));case "audit"->s.db.queryForList("SELECT id,actor_name AS name,action,created_at AS createdAt FROM audit_events WHERE tenant_id=? AND (? IS NULL OR created_at>=?) AND (? IS NULL OR created_at<?) ORDER BY created_at DESC LIMIT 5001",p.tenantId(),start,start==null?null:start.atStartOfDay(),end,end==null?null:end.plusDays(1).atStartOfDay());default->{String entityKind=switch(kind){case "inventory"->"items";case "invoices"->"invoices";default->"payrollRuns";};yield s.db.queryForList("SELECT id,payload,status,total,currency,created_at AS createdAt FROM business_entities WHERE tenant_id=? AND kind=? AND (? IS NULL OR created_at>=?) AND (? IS NULL OR created_at<?) AND (?='' OR status=?) ORDER BY created_at DESC LIMIT 5001",p.tenantId(),entityKind,start,start==null?null:start.atStartOfDay(),end,end==null?null:end.plusDays(1).atStartOfDay(),Objects.toString(filters.get("status"),""),Objects.toString(filters.get("status"),"")).stream().map(row->{var value=s.decode(row.get("payload"));value.put("id",row.get("id"));value.put("status",row.get("status"));value.put("total",row.get("total"));value.put("currency",row.get("currency"));value.put("createdAt",row.get("createdAt"));return value;}).toList();}};
        if(result.size()>5000)throw new ApiException(400,"Source report exceeds 5,000 rows. Reduce the source range before export; no partial snapshot was created.");String status=Objects.toString(filters.get("status"),"");if(!status.isBlank())result=result.stream().filter(r->status.equals(Objects.toString(r.get("status"),""))).toList();
        if(start!=null||end!=null){if(Set.of("employees","projects").contains(kind)){var ids=new HashSet<>(s.db.queryForList("SELECT id FROM business_records WHERE tenant_id=? AND kind=? AND (? IS NULL OR created_at>=?) AND (? IS NULL OR created_at<?)",String.class,p.tenantId(),kind,start,start==null?null:start.atStartOfDay(),end,end==null?null:end.plusDays(1).atStartOfDay()));result=result.stream().filter(r->ids.contains(r.get("id"))).toList();}else result=result.stream().filter(r->{String raw=Objects.toString(r.getOrDefault("createdAt",r.getOrDefault("workDate",r.get("startDate"))),"");if(raw.length()<10)return false;try{LocalDate day=LocalDate.parse(raw.substring(0,10));return(start==null||!day.isBefore(start))&&(end==null||!day.isAfter(end));}catch(Exception ex){return false;}}).toList();}
        if(result.size()>5000)throw new ApiException(400,"Report exceeds 5,000 rows. Narrow the filters.");return result;
    }
    @Transactional public Map<String,Object> generate(Principal p,String name,String kind,Map<String,Object> filters,String definitionId){if(!custom.allowed(p,"POST","/api/v1/org/reports/exports"))throw new ApiException(403,"Custom role cannot create report exports.");s.lock(p,"REPORTS",false);List<Map<String,Object>> rows=rows(p,kind,filters);List<String> columns=columns(kind);StringBuilder csv=new StringBuilder(String.join(",",columns)).append("\r\n");for(var row:rows){for(int i=0;i<columns.size();i++){if(i>0)csv.append(',');csv.append(cell(row.get(columns.get(i))));}csv.append("\r\n");}String id=s.id();s.db.update("INSERT INTO report_exports(id,tenant_id,owner_id,definition_id,name,kind,content,row_manifest,row_count,status,expires_at) VALUES (?,?,?,?,?,?,?,?,?,'READY',TIMESTAMPADD(DAY,7,UTC_TIMESTAMP(6)))",id,p.tenantId(),p.userId(),definitionId,name,kind,csv.toString(),s.encode(Map.of("ids",rows.stream().map(r->r.get("id")).filter(Objects::nonNull).toList())),rows.size());s.audit.log(p,"REPORT_EXPORTED","reportExport",id);s.events.notify(p.tenantId(),p.userId(),id,"REPORT_READY","Report ready",name+" contains "+rows.size()+" authorized rows and expires in seven days.");return s.db.queryForMap("SELECT id,name,kind,status,row_count AS rowCount,expires_at AS expiresAt,created_at AS createdAt FROM report_exports WHERE id=?",id);}
    public byte[] content(Principal p,String id){if(!custom.allowed(p,"GET","/api/v1/org/reports/exports/"+id+"/download"))throw new ApiException(403,"Custom role cannot download report exports.");var row=s.first(s.db.queryForList("SELECT * FROM report_exports WHERE tenant_id=? AND id=? AND expires_at>UTC_TIMESTAMP(6) AND status='READY'",p.tenantId(),id),"Report export");if(!p.userId().equals(row.get("owner_id")))throw new ApiException(403,"Only the report requester can download this snapshot.");String kind=row.get("kind").toString();authorize(p,kind);if(Set.of("projects","attendance","leaves").contains(kind)){List<Map<String,Object>> current=kind.equals("projects")?workforce.list(p,"projects"):kind.equals("attendance")?workforce.attendance(p):workforce.leaves(p);var accessible=new HashSet<>(current.stream().map(r->Objects.toString(r.get("id"),"")).toList());Object manifest=s.decode(row.get("row_manifest")).get("ids");if(manifest instanceof List<?> ids&&!accessible.containsAll(ids.stream().map(Object::toString).toList()))throw new ApiException(403,"Access to source rows changed. Generate a fresh report.");}return row.get("content").toString().getBytes(java.nio.charset.StandardCharsets.UTF_8);}
    private String sourcePath(String kind){return "/api/v1/org/"+switch(kind){case "employees","projects"->"records/"+kind;case "attendance"->"attendance";case "leaves"->"leave/requests";case "audit"->"audit-events";case "inventory"->"business/records/items";case "invoices"->"business/records/invoices";default->"business/records/payrollRuns";};}
    private LocalDate date(Map<String,Object> filters,String name){Object value=filters.get(name);if(value==null||value.toString().isBlank())return null;try{return LocalDate.parse(value.toString());}catch(Exception ex){throw new ApiException(400,name+" must be an ISO date.");}}
    private static List<String> columns(String kind){return switch(kind){case "employees"->List.of("id","name","employeeCode","status","departmentId","joinDate");case "projects"->List.of("id","name","status","ownerId");case "audit"->List.of("id","name","action","createdAt");case "attendance"->List.of("id","name","workDate","inAt","outAt","lateMinutes","overtimeMinutes");case "leaves"->List.of("id","name","type","startDate","endDate","days","status");default->List.of("id","name","status","total","currency","createdAt");};}
    private static String cell(Object value){if(value==null)return "";String text=value.toString();if(!(value instanceof Number)&&!text.isEmpty()&&"=+-@\t\r".indexOf(text.charAt(0))>=0)text="'"+text;return "\""+text.replace("\"","\"\"")+"\"";}
}
